function Timer({ step }) {
  const [count, setCount] = useState(0);

  useEffect(() => {
    const id = setInterval(() => {
      setCount((c) => c + step); // step을 의존성에서 빠뜨리면 첫 렌더의 step만 계속 씀
    }, 1000);
    return () => clearInterval(id); // 클린업: 이전 interval 정리
  }, [step]);

  return count;
}
